PEND = "Explicação pendente"
total, por_obj = 0, {}
for obj, mapa in CAMPOS.items():
    o = ld(f"objetos-api/{obj}.json")
    src = f"src:objref-{obj.lower()}-completa"
    n = 0
    for c in o["campos"]:
        if not c["o_que_e"].startswith(PEND):
            continue
        fonte, item = (src, mapa.get(c["nome"])) if c["nome"] in mapa else (SIS, SISTEMA.get(c["nome"]))
        if item is None:
            continue
        tipo, texto = item
        c["o_que_e"] = texto
        c["explicacao"] = "explicada"
        if tipo and c.get("tipo_tecnico") in (None, "", "(a extrair)"):
            c["tipo_tecnico"] = tipo
        if not any(e["fonte"] == fonte for e in c["evidencias"]):
            c["evidencias"].append(ev(fonte))
        c["notas"] = [x for x in c.get("notas", []) if not x.startswith("Nome listado na Object Reference; tipo e propriedades não extraídos")]
        n += 1
    if not any(e["fonte"] == SIS for e in o["evidencias"]) and any(
            c["nome"] in SISTEMA and any(e["fonte"] == SIS for e in c["evidencias"]) for c in o["campos"]):
        o["evidencias"].append(ev(SIS))
    sv(f"objetos-api/{obj}.json", o)
    por_obj[obj] = n
    total += n
print("lote 7v:", total, "campos explicados", por_obj)
